"""Build the self-contained observational Pine indicator from the shared market core."""

import argparse
import hashlib
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
PINE = ROOT / "unified" / "experimental"
TARGET = PINE / "QIRVANTA_SNIPER_V22_INTELLIGENCE.pine"
FRAGMENTS = PINE / "v22"
HEADER = (
    '//@version=6\n'
    'indicator("QIRVANTA V2.2 · Intelligence", shorttitle="QIRV V2.2 Intel", overlay=true, calc_bars_count=3600)\n'
    '// Generated by unified/tools/build_v22_intelligence.py. Edit the fragments under experimental/v22.\n'
)


def build():
    parts = [HEADER.rstrip()]
    for name in ("market_core.pineinc", "intelligence_tail.pineinc"):
        parts.append((FRAGMENTS / name).read_text(encoding="utf-8").strip())
    return ("\n\n".join(parts) + "\n").encode("utf-8")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if the checked-in indicator differs")
    args = parser.parse_args()
    payload = build()
    if args.check:
        if not TARGET.is_file() or TARGET.read_bytes() != payload:
            parser.error(f"{TARGET.name} differs from its fragments")
    else:
        TARGET.write_bytes(payload)
    print(f"{TARGET.name} {len(payload)} bytes sha256={hashlib.sha256(payload).hexdigest()}")


if __name__ == "__main__":
    main()
